    "user": {
        "name": {
            "type": "string",
            "required": True,
            "min_length": 1,
            "max_length": 100,
        },
        "email": {
            "type": "string",
            "required": True,
            "pattern": EMAIL_PATTERN,
        },
        "age": {
            "type": "int",
            "required": False,
            "min_value": 0,
            "max_value": 150,
        },
